class Solution {
public:
    string minimizeError(vector<string>& prices, int target) {
        int min_sum = 0;
        vector<double> fracs;
        for (const string& p : prices) {
            double val = stod(p);
            int f = floor(val);
            min_sum += f;
            double frac = val - f;
            if (frac > 1e-9) {
                fracs.push_back(frac);
            }
        }

        int max_sum = min_sum + fracs.size();
        if (target < min_sum || target > max_sum) return "-1";

        int k = target - min_sum;
        sort(fracs.begin(), fracs.end(), greater<double>());

        double total_error = 0.0;
        for (int i = 0; i < k; ++i) {
            total_error += (1.0 - fracs[i]);
        }
        for (int i = k; i < (int)fracs.size(); ++i) {
            total_error += fracs[i];
        }

        char buf[32];
        snprintf(buf, sizeof(buf), "%.3f", total_error);
        return string(buf);
    }
};

class Solution {
    public String minimizeError(String[] prices, int target) {
        int minSum = 0;
        List<Double> fracs = new ArrayList<>();
        for (String p : prices) {
            double val = Double.parseDouble(p);
            int f = (int) Math.floor(val);
            minSum += f;
            double frac = val - f;
            if (frac > 1e-9) {
                fracs.add(frac);
            }
        }

        int maxSum = minSum + fracs.size();
        if (target < minSum || target > maxSum) return "-1";

        int k = target - minSum;
        fracs.sort(Collections.reverseOrder());

        double totalError = 0.0;
        for (int i = 0; i < k; ++i) {
            totalError += (1.0 - fracs.get(i));
        }
        for (int i = k; i < fracs.size(); ++i) {
            totalError += fracs.get(i);
        }

        return String.format(Locale.US, "%.3f", totalError);
    }
}

var minimizeError = function(prices, target) {
    let minSum = 0;
    const fracs = [];
    for (const p of prices) {
        const val = parseFloat(p);
        const f = Math.floor(val);
        minSum += f;
        const frac = val - f;
        if (frac > 1e-9) {
            fracs.push(frac);
        }
    }

    const maxSum = minSum + fracs.size !== undefined ? minSum + fracs.size : minSum + fracs.length;
    if (target < minSum || target > maxSum) return "-1";

    const k = target - minSum;
    fracs.sort((a, b) => b - a);

    let totalError = 0.0;
    for (let i = 0; i < k; i++) {
        totalError += 1.0 - fracs[i];
    }
    for (let i = k; i < fracs.length; i++) {
        totalError += fracs[i];
    }

    return totalError.toFixed(3);
};
